#!/bin/sh
# Runs one check with TLC and summarises it.
#
#   tools/check.sh <name> <CONFIG> <quint verify options...>
#
# <CONFIG> is a `Cfg` of configs.qnt. The check is the module
# `out/<name>.qnt`, which instantiates queue.qnt with it. The whole TLC
# output goes to out/<name>.txt; this prints the verdict, the state counts,
# the wall time and, for a counterexample, the number of states in it
# (the steps are one fewer) and its summary in out/<name>.trace.
set -u
name=$1
config=$2
shift 2
cd "$(dirname "$0")/.." || exit 2
mkdir -p out
cat > "out/$name.qnt" <<EOF
// Generated by tools/check.sh: queue.qnt with $config.
module $name {
  import configs.* from "../configs"
  import queue(C = $config).* from "../queue"
}
EOF
# TLC keeps its state queue and fingerprints under the temp dir, gigabytes
# for the large checks; keep them under out/tmp (or $TLC_TMP, to keep
# them off the checkout) and remove them after.
tmp="${TLC_TMP:-$PWD/out/tmp}/$name"
rm -rf "$tmp"; mkdir -p "$tmp"
start=$(date +%s)
TMPDIR="$tmp" npx quint verify --backend=tlc --main="$name" "$@" "out/$name.qnt" > "out/$name.txt" 2>&1
status=$?
rm -rf "$tmp"
end=$(date +%s)
echo "== $name ($config $*): exit $status, $((end - start)) s"
grep -E "distinct states found, [0-9]+ states left|depth of the complete|No violation|Found an issue|Model checking completed|error:" "out/$name.txt"
if grep -q "^State 1:" "out/$name.txt"; then
  python3 -I tools/trace.py < "out/$name.txt" > "out/$name.trace"
  grep -cE "^ +[0-9]+ <" "out/$name.trace" | sed 's/^/states in trace: /'
fi
exit $status
